const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_4","ls":"6.4","title":"Lernpfadübung · LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_4_Selbstbedienungsflaeche_gestalten.md"};
const COMP=[["Fachkompetenz","Ich gestalte eine Selbstbedienungsfläche. Ich begründe, wie der Kundenlauf, die Plätze für die Artikel und die Produktinformationen der Kundschaft helfen. Die Kundschaft soll die Ware selbst finden, vergleichen und auswählen können."],["Personalkompetenz","Ich prüfe, ob eine Person sich mit meinem Entwurf zurechtfindet, wenn sie die Aktionsfläche noch nicht kennt."],["Sozialkompetenz","Ich höre mir Rückmeldungen dazu an, wie gut andere sich zurechtfinden. Ich erkläre dem Team, was ich deshalb ändere."],["Methodenkompetenz","Ich trage meine Beobachtungen zu den Kundenwegen und die Produktdaten in den Lageplan ein."],["Medienkompetenz","Ich gestalte Orientierungsschilder und Produktinformationen so, dass die Kundschaft sie an der vorgesehenen Stelle gut lesen und verstehen kann."]];
const BANK=[{"title":"Was Sarah und Sebastian beobachten","scene":"Sarah Huber aus dem Marketing und Sebastian Wolf aus dem Außendienst besuchen die Bike Arena Oltmanns in Leer. Die Zubehörfläche für die Frühjahrsaktion wird vorbereitet.","ask":"Welche Aussagen treffen zu?","options":["Sarah möchte, dass Familien die Aktion früh bemerken.","Sebastian achtet darauf, ob die Kundschaft Platz zum Stehen und Vergleichen hat.","Sebastian plant eine feste Beratung an der Zubehörfläche für Samstag.","Sarah möchte, dass die Kundschaft erst in der Fahrradabteilung von der Aktion erfährt.","Die beiden prüfen, wie Sichtbarkeit und Bewegungsraum zusammenpassen.","Sarah und Sebastian wollen die Auswahl der Produkte erst nach der Aktion prüfen."],"answer":[0,1,4],"why":"Sarah achtet auf frühe Sichtbarkeit. Sebastian greift die Platzfrage auf. Am Samstag ist in der Aktion keine feste Beratung vorgesehen.","hint":"Sammle je eine Aussage von Sarah und Sebastian.","steps":"Ordne die Aussagen den Fragen nach dem ersten Blick und dem Platz beim Stehenbleiben zu.","example":"Ein günstig platzierter Hinweis hilft beim Finden. Der stehende Einkaufswagen braucht trotzdem Platz.","c":2,"sourceRefs":["Handlungssituation","M2"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen Einkauf aus Sicht der Kundschaft betrachten","scene":"Ein Vater und sein Sohn nehmen je eine Pumpe in die Hand. Sie suchen nach einem Modell für das Rad des Kindes. Der Vater stellt beide Pumpen zurück und geht weiter.","ask":"Welche Beobachtungen sollte dein eigener Entwurf bei der Probe aufgreifen?","options":["Der Vater sucht auf der Rückseite der Verpackung eine Angabe zur Ventilart.","Der Sohn findet die passende Pumpe mithilfe einer Preisaktion.","Der Wagen steht im Weg, sodass andere ausweichen müssen.","Der Vater stellt beide Pumpen zurück, ohne eine auszuwählen.","Die Familie nutzt einen Wegweiser zur Kasse als Ventilhinweis.","Eine Verkäuferin erklärt, warum beide Modelle passen."],"answer":[0,2,3],"why":"Die beobachtete Suche und das Zurücklegen zeigen, was dein Entwurf bei der Auswahl prüfen sollte. Im selben Test lässt sich beobachten, ob der Wagen anderen den Weg lässt.","hint":"Versetze dich in die Familie und in eine vorbeigehende Person.","steps":"Notiere, was im Fall beim Suchen, beim Stehenbleiben und bei der Auswahl geschieht.","example":"Das Zurückstellen eines Artikels ist beobachtbar. Die Motivation kann durch eine gezielte Frage geklärt werden.","c":1,"sourceRefs":["Handlungssituation","M2","M5"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was Selbstbedienung bedeutet","scene":"An der Aktionsfläche ist am Samstag keine feste Beratung eingeplant.","ask":"Woran erkennst du eine funktionierende Selbstbedienungsfläche?","options":["Der Weg zur Ware ist für Kundinnen und Kunden erkennbar.","Alle Informationen zur Eignung werden durch das Personal vorgelesen.","Die Kundschaft kann die passenden Artikel selbst vergleichen.","Die Kundschaft kann Ware selbst vom Warenplatz nehmen.","Das Personal muss die Ware nach jeder Produktfrage aus dem Lager holen.","Die Produkte stehen so, dass nur das Personal sie greifen kann."],"answer":[0,2,3],"why":"In der Selbstbedienung findet, vergleicht und greift die Kundschaft die Ware überwiegend selbst. Schilder, lesbare Produktangaben und nutzbare Bedienseiten unterstützen diese Schritte.","hint":"Denk an den Einkauf von der ersten Orientierung bis zum Griff ins Regal.","steps":"Prüfe, welche Schritte eine Kundin oder ein Kunde selbst erledigen kann.","example":"Ein Hinweis am Regal kann helfen, die Wahl zwischen zwei Pumpen selbst zu treffen.","c":0,"sourceRefs":["Handlungssituation","M5","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Kundenlauf einzeichnen","scene":"Vom Zugang gehen einige Personen direkt zur Fahrradabteilung. Familien halten mit Wagen am Rand der Aktionsfläche an, um zu lesen.","ask":"Welche Einträge bilden diese Beobachtungen sinnvoll ab?","options":["Der Kundenlauf ist die Zeit zwischen Öffnung und Ladenschluss.","Ein Pfeil führt vom Zugang Richtung Fahrradabteilung.","Ein möglicher Lesepunkt am Rand der Aktion wird markiert.","Nur Kundschaft, die bereits gekauft hat, wird im Plan berücksichtigt.","Am Lesepunkt wird geprüft, ob dort ein Einkaufswagen den Weg verengt.","Die Fahrradabteilung wird mit dem Orientierungsschild gleichgesetzt."],"answer":[1,2,4],"why":"Der Kundenlauf beschreibt Bewegungen im Laden. Ein Pfeil zeigt die Laufrichtung, eine Markierung den beobachteten Halt. Zusammen helfen die beiden Einträge, mögliche Engstellen zu erkennen.","hint":"Suche nach dem tatsächlich beschriebenen Weg und der Stelle zum Lesen.","steps":"Zeichne Bewegung und Halt mit verschiedenen Zeichen ein.","example":"Eine Person, die stehen bleibt, beansprucht Platz an einer bestimmten Stelle auf dem Wegplan.","c":3,"sourceRefs":["M1","M2","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Gondel, Bedienzone und Zugangsweg","scene":"In der Bike Arena stehen zwei drehbare Gondeln zur Verfügung. Ware steht auf beiden langen Seiten jeder Gondel.","ask":"Welche Aussagen stimmen?","options":["Eine Gondel ist ein frei im Raum stehendes Verkaufsregal.","Die Bedienzone ist der freie Streifen vor der Warenseite.","Der Schildfuß darf in der Bedienzone stehen, wenn die Ware sichtbar bleibt.","Es genügt, nur eine der beiden langen Seiten erreichbar zu halten.","Alle Bedienseiten müssen vom Hauptgang aus erreichbar sein.","Die Bedienzone bezeichnet das oberste Regalfach."],"answer":[0,1,4],"why":"Die Gondeln tragen Ware an beiden langen Seiten. Vor jeder Seite bleibt ein Freistreifen zum Sehen und Greifen. Die Kundschaft muss diese Flächen vom Hauptgang aus erreichen können.","hint":"Unterscheide das Möbelstück, den freien Streifen davor und den Weg dorthin.","steps":"Gehe gedanklich vom Hauptgang bis zum Griff ins Regal.","example":"Auch bei einem gut sichtbaren Regal kann ein Gegenstand den Zugang versperren.","c":0,"sourceRefs":["M1","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Schild oder Produktkarte?","scene":"Die Kundschaft kommt vom Eingang oder aus der Fahrradabteilung und möchte eine Pumpe finden und auswählen.","ask":"Welche Informationen haben die passende Aufgabe?","options":["Das Wort „Autoventil“ auf der Pumpenkarte hilft, die Kompatibilität zu prüfen.","Eine Karte mit der Pumpenlänge ersetzt den Hinweis, wo die Aktionsfläche liegt.","Ein Schild „Fahrradzubehör“ mit Pfeil kann zur Aktionsfläche führen.","Ein Logo auf dem Schild enthält schon alle Angaben zum Pumpenvergleich.","Die Angabe zum Manometer auf der Pumpenkarte hilft beim Vergleich.","Die farbliche Markierung des Hauptgangs ist die Ventilinformation zur Minipumpe."],"answer":[0,2,4],"why":"Ein Orientierungsschild führt zur richtigen Fläche. Produktkarten am Warenplatz helfen beim Vergleich von Ventilart oder Ausstattung.","hint":"Unterscheide „Wo finde ich es?“ und „Was passt zu meinem Bedarf?“.","steps":"Ordne jede Information einer Frage zu. Prüfe, ob sie diese Frage beantwortet.","example":"„Pumpen →“ hilft bei der Suche. „Mit Druckanzeige“ hilft bei der Wahl im Regal.","c":4,"sourceRefs":["M1","M3","M5","M6"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Pumpen, eine Warengruppe","scene":"In der Aktion steht die Minipumpe P50. Ein Exemplar der Standpumpe P51 aus dem normalen Angebot darf für den Vergleich dazugestellt werden.","ask":"Welche Aussagen sind richtig?","options":["P50 hat eine Druckanzeige.","P50 und P51 bilden als Pumpen eine Warengruppe.","P51 hat ein Manometer.","Die Standpumpe darf auch auf der Gondel stehen.","P51 passt ausschließlich auf Autoventile.","P50 ist für unterwegs gedacht."],"answer":[1,2,3,5],"why":"Beide Pumpen gehören zu einer Warengruppe. P50 ist für unterwegs gedacht und hat keine Druckanzeige. P51 bringt ein Manometer mit und darf als Vergleichsartikel auf die Gondel.","hint":"Lies die beiden Pumpenzeilen in M3 getrennt.","steps":"Vergleiche Warengruppe, Einsatz und Ausstattung und prüfe die Aufstellregel in M1.","example":"Ein Vergleichsartikel kann aus dem normalen Angebot kommen und trotzdem bei der Auswahl helfen.","c":0,"sourceRefs":["M1","M3","M6"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was beim Flaschenhalter passen muss","scene":"Eine Kundin hat eine Flasche mit 74 mm Durchmesser. Sie sieht zwei freiliegende Gewinde am Rahmen. Ihr Abstand ist noch unbekannt.","ask":"Welche Aussagen helfen bei der Auswahl von F60?","options":["74 mm liegen bei der Flasche im vorgesehenen Bereich.","Der Flaschenhalter ist für Flaschen von genau 64 mm Durchmesser gedacht.","Zwei sichtbare Gewinde reichen als endgültiger Eignungsnachweis für die Montage.","Die Kundin muss am Rahmen den Gewindeabstand prüfen.","Die Schrauben liegen bei.","Der Durchmesser der Flasche gibt den Abstand der Rahmengewinde an."],"answer":[0,3,4],"why":"Die Flasche passt nach dem Durchmesser in den Bereich 72–75 mm. Für die Montage müssen die beiden passenden Gewinde am Fahrrad 64 mm Abstand haben. Schrauben sind bereits enthalten.","hint":"Betrachte Flasche und Fahrradrahmen getrennt.","steps":"Vergleiche den Flaschendurchmesser mit dem Bereich. Suche dann das eigene Maß für den Rahmen.","example":"Durchmesser und Abstand beschreiben zwei verschiedene Merkmale.","c":0,"sourceRefs":["M2","M3","M6"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was im Grundriss frei bleibt","scene":"In M1 liegen der Hauptgang und der Durchgang zur Fahrradabteilung neben der geplanten Aktion. Warenträger und Schilder stehen auf der Aktionsfläche.","ask":"Welche Aussagen stimmen?","options":["Der Hauptgang ist nur an seiner schmalsten Stelle freizuhalten.","Der Hauptgang liegt zwischen y = 0,00 m und y = 1,50 m.","Der Durchgang zur Fahrradabteilung liegt im östlichen Streifen zwischen x = 6,40 m und x = 8,00 m.","Die Gondeln dürfen quer im Hauptgang stehen, wenn sie gut sichtbar sind.","Hauptgang und Durchgang zur Fahrradabteilung bleiben in voller Breite frei.","Die Aktionsfläche füllt sämtliche 8,00 m Breite oberhalb des Hauptgangs."],"answer":[1,2,4],"why":"Der Hauptgang verläuft von West nach Ost. Der östliche Streifen oberhalb davon führt zur Fahrradabteilung. Die Aktionsfläche liegt westlich neben diesem Streifen.","hint":"Suche in M1 nach y für den Hauptgang und nach x für den östlichen Durchgang.","steps":"Trenne die farblich markierbaren Rechtecke anhand ihrer Koordinaten.","example":"Zwei benachbarte Flächen können eine gemeinsame Grenze haben und verschiedene Funktionen erfüllen.","c":3,"sourceRefs":["M1"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Karte hilft beim Vergleichen?","scene":"Die Pumpenverpackungen sehen ähnlich aus. Die Kundschaft braucht schnell erkennbare Angaben direkt an der Gondel.","ask":"Welche Merkmale machen die Karte hilfreich?","options":["Beide Pumpen haben dieselben Zeilen für Ventilarten, Einsatz und Druckanzeige.","Die eigentliche Ventilangabe steht nur hinten auf einer einzelnen Verpackung.","Die Karte ist dort befestigt, wo die Kundschaft die Pumpen greift und vergleicht.","Fachwörter werden bei Bedarf erklärt, etwa „Manometer = Druckanzeige“.","Für die Minipumpe wird eine Druckanzeige angegeben, damit die Karten gleich aussehen.","Die Karte enthält nur Bilder ohne Produktbezug."],"answer":[0,2,3],"why":"Gleiche Kategorien machen den Vergleich leicht. Die Angaben müssen stimmen und am Ort der Auswahl gut lesbar sein. Ein erklärtes Fachwort hilft beim Verstehen.","hint":"Überlege, welche Frage an der Gondel ohne Beratung geklärt werden muss.","steps":"Prüfe Lesbarkeit, Standort und fachliche Richtigkeit der Angaben.","example":"Zwei Spalten mit denselben Zeilen lassen Unterschiede auf einen Blick erkennen.","c":4,"sourceRefs":["M1","M3","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die eigene Planung mit fremden Augen prüfen","scene":"Dein Team kennt die Skizze sehr gut. Eine andere Person sieht die Fläche zum ersten Mal.","ask":"Welche Prüfungen helfen, die tatsächliche Orientierung einzuschätzen?","options":["Das Team erklärt der Testperson vorab alle Schilder und Wege.","Die Testperson sagt, wo ihr der erste Hinweis auffällt.","Die Testperson sucht zu Beginn ohne vorgelesene Wegbeschreibung.","Das Team wertet allein das eigene Wissen über die Produktplätze aus.","Ein zweiter Startpunkt aus der Fahrradabteilung wird ausprobiert.","Die Testperson wartet beim Regal auf Anweisungen, bevor sie die richtige Pumpe auswählt."],"answer":[1,2,4],"why":"Eine unvoreingenommene Testperson zeigt, was der Aufbau selbst vermittelt. Der erste bemerkte Hinweis und verschiedene Startpunkte machen den Beobachtungsbogen aussagekräftig.","hint":"Denk an eine Person, die eure Planung noch nie gesehen hat.","steps":"Gib ein Einkaufsziel vor und beobachte, wann ein Hinweis gefunden wird.","example":"Wenn der Testperson der Weg vorab erklärt wird, prüft sie vor allem, ob sie sich an die Erklärung erinnert.","c":1,"sourceRefs":["M2","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Rückmeldung konkret nutzen","scene":"Eine Testperson berichtet: „Ich sehe die Pumpen. Beim Lesen weiß ich aber nicht, welche Angaben zu welcher Pumpe gehören.“","ask":"Welche Reaktionen passen zur Rückmeldung?","options":["Die Rückmeldung als Beobachtung im Team weitergeben.","Die Karte mit klaren Spalten für P50 und P51 beschriften und erneut testen.","Die Regalbeschriftung entfernen, damit alle Karten gleich leer sind.","Die Rückmeldung allein als Wunsch nach größerer Schrift zusammenfassen.","Nachfragen, bei welcher Zeile oder Spalte die Zuordnung schwierig war.","Die Pumpen in einen anderen Laden verlegen."],"answer":[0,1,4],"why":"Die geschilderte Schwierigkeit betrifft die Zuordnung. Eine Rückfrage nennt die konkrete Stelle. Klar beschriftete Spalten und ein Wiederholungstest machen die Änderung überprüfbar.","hint":"Achte darauf, welche Schwierigkeit genau genannt wurde.","steps":"Besprecht gemeinsam Ursache, passende Änderung und eine kurze Nachprobe.","example":"Eine gut lesbare Zahl bleibt mehrdeutig, wenn die Spaltenüberschrift fehlt.","c":2,"sourceRefs":["M3","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßstab für Fläche und Verkehrswege","scene":"Der Modellgrundriss ist 8,00 m breit und 5,00 m tief. Der Maßstab ist 1:25. Der Hauptgang ist 1,50 m breit.","ask":"Welche Maße stimmen auf dem Papier?","options":["Der ganze Bereich ist 32 cm × 20 cm groß.","Der ganze Bereich ist 20 cm × 12,5 cm groß.","Der Hauptgang ist 3,75 cm breit.","Der Hauptgang ist 6,0 cm breit.","Die 5,00 m Tiefe ergeben 25,0 cm.","1 cm auf dem Papier entspricht 25 cm im Laden."],"answer":[0,3,5],"why":"Rechne die wirklichen Maße in Zentimeter um und teile durch 25. 800 cm ergeben 32 cm, 500 cm ergeben 20 cm und 150 cm ergeben 6 cm.","hint":"Schreib 8,00 m, 5,00 m und 1,50 m zunächst als Zentimeter.","steps":"Teile jeden Wert durch 25. Vergleiche dann Hauptgang, Breite und Tiefe.","example":"2 cm auf dem Blatt entsprechen hier 50 cm im Laden.","c":3,"sourceRefs":["M1"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Bauteile im Gondelmodell","scene":"Eine Gondel misst 1,60 m × 0,60 m. Der Schildfuß misst 0,40 m × 0,40 m. Vor jeder langen Seite bleiben 1,20 m als Bedienzone frei. Das Modell hat den Maßstab 1:25.","ask":"Welche Maße brauchst du im Modell?","options":["Die Gondel misst 4,0 cm × 2,4 cm.","Der Schildfuß misst 1,6 cm × 1,6 cm.","Eine Bedienzone ist 4,8 cm breit.","Die Gondel misst 6,4 cm × 2,4 cm.","Eine Bedienzone ist 3,0 cm breit.","Der Schildfuß misst 4,0 cm × 4,0 cm."],"answer":[1,2,3],"why":"Gondel: 160 cm ÷ 25 = 6,4 cm und 60 cm ÷ 25 = 2,4 cm. Schildfuß: 40 cm ÷ 25 = 1,6 cm je Seite. Bedienzone: 120 cm ÷ 25 = 4,8 cm.","hint":"Setze für jedes Bauteil immer denselben Maßstab ein.","steps":"Rechne jede Seitenlänge einzeln um und ordne sie dem richtigen Bauteil zu.","example":"50 cm im Laden brauchen bei 1:25 im Modell 2 cm.","c":3,"sourceRefs":["M1","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Möbel an der Grenze prüfen","scene":"Übungsvariante: Eine Gondel reicht von x = 5,10 m bis x = 6,70 m. Ihre gesamte y-Ausdehnung liegt oberhalb von y = 1,50 m. Ab x = 6,40 m beginnt dort der Durchgang zur Fahrradabteilung.","ask":"Welche Prüfergebnisse stimmen?","options":["Die Gondel ragt in den Hauptgang, weil sie westlich der Fahrradabteilung beginnt.","Die Gondel ragt 0,30 m in den Durchgang zur Fahrradabteilung.","Das Regal darf stehen bleiben, wenn ein Pfeil zur westlichen Bedienseite zeigt.","Der neue Standort muss den Durchgang und die erreichbaren Bedienseiten berücksichtigen.","Eine Drehung des Wegpfeils allein stellt die volle Gangbreite wieder her.","Die Koordinaten der Gondel sind mit der Begrenzung der Aktionsfläche vereinbar."],"answer":[1,3],"why":"Die rechte Kante liegt bei x = 6,70 m. Der Durchgang beginnt bei x = 6,40 m. Die Überlappung von 30 cm verletzt die Vorgabe. Nach einer Verschiebung ist auch die Erreichbarkeit erneut zu prüfen.","hint":"Vergleiche die rechte x-Grenze des Möbels mit x = 6,40 m.","steps":"Berechne die Überschneidung und unterscheide Möbel- und Bedienfläche.","example":"Die Position des Möbelkörpers ist zuerst zu prüfen, bevor du seine Bedienseite einzeichnest.","c":3,"sourceRefs":["M1"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Schildfuß vor dem Regal","scene":"Übungsvariante: Im Plan ist die Bedienzone 1,20 m breit. Der Schildfuß ragt an einer Stelle 0,20 m in diesen Streifen hinein.","ask":"Welche Feststellungen sind richtig?","options":["Die nutzbare Breite beträgt an dieser Stelle 1,00 m.","Die Zone erfüllt die Regel, weil sie auf dem Plan ursprünglich 1,20 m breit eingezeichnet war.","Der Schildfuß steht teilweise in einem Bereich, der für den Zugriff frei bleiben muss.","Das Schild sollte außerhalb der Bedienzone auf der Aktionsfläche platziert und auf Sichtbarkeit geprüft werden.","Wird der Schildtext deutlich größer, zählt der Schildfuß als Teil des freien Streifens.","0,20 m entsprechen 0,20 cm im Maßstab 1:25."],"answer":[0,2,3],"why":"Der Fuß verengt den Streifen an der Stelle auf 1,00 m. In der Bedienzone steht kein Schildfuß. Der richtige neue Standort ist sowohl an den Flächenregeln als auch an der Sichtbarkeit zu prüfen.","hint":"Suche die tatsächliche Engstelle am Boden.","steps":"Ziehe den belegten Teil von der Streifenbreite ab. Prüfe anschließend, wo der Fuß anders stehen kann.","example":"Ein am Regal befestigter kleiner Hinweis braucht keinen zusätzlichen Fuß auf dem Boden.","c":3,"sourceRefs":["M1","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei kompatible Pumpen sinnvoll unterscheiden","scene":"Ein Vater braucht eine Pumpe für ein Autoventil. Er möchte sie in einer kleinen Tasche mitnehmen. Eine Druckanzeige braucht er nicht.","ask":"Welche Angaben und Folgerungen stimmen?","options":["Nur P51 passt laut Produktkarte zum Autoventil.","P50 und P51 passen laut Produktkarten zum Autoventil.","P50 ist mit 18 cm für den beschriebenen Einsatz unterwegs die naheliegende Wahl.","P50 muss wegen eines Manometers ausgewählt werden.","P51 ist laut Produktkarte 62 cm hoch und hat ein Manometer.","Die passende Ventilart entscheidet allein, welche Größe der Vater braucht."],"answer":[1,2,4],"why":"Beide Pumpenköpfe können am Autoventil genutzt werden. Für die kleine Tasche ist P50 mit 18 cm und ohne Druckanzeige die passendere Wahl. P51 ist größer und bietet eine Druckanzeige.","hint":"Kläre zuerst die Kompatibilität. Prüfe erst danach Größe und gewünschten Einsatz.","steps":"Vergleiche die beiden Produktkarten in denselben drei Kategorien.","example":"Wenn zwei Angebote zur selben Ventilart passen, hilft oft ein zweites Merkmal bei der Entscheidung.","c":0,"sourceRefs":["M2","M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine verlässliche Karte für F60","scene":"Die Produktkarte für F60 nennt geeignete Flaschen mit 72 bis 75 mm Durchmesser, zwei passende Rahmengewinde mit 64 mm Abstand und mitgelieferte Schrauben.","ask":"Welche Texte können auf einem kurzen, verlässlichen Schild stehen?","options":["„Die Flasche muss 64 mm Durchmesser haben.“","„Zwei passende Gewinde am Rahmen: Abstand 64 mm.“","„Mit Schrauben: passt an jede Stelle am Rahmen.“","„Für Flaschen mit 72–75 mm Durchmesser.“","„Schrauben liegen bei.“","„Zwei sichtbare Gewinde garantieren die Montage.“"],"answer":[1,3,4],"why":"Der Durchmesser beschreibt die passende Flasche. Der Abstand betrifft den Rahmen. Mitgelieferte Schrauben sind eine Zusatzangabe; die Kundschaft muss den Rahmen trotzdem prüfen.","hint":"Achte darauf, welches Maß zu welchem Gegenstand gehört.","steps":"Prüfe jeden Text am passenden Eintrag aus M3.","example":"Ein Schild kann eine Frage beantworten und zugleich zeigen, welche Messung am Rad noch fehlt.","c":4,"sourceRefs":["M2","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Weitere Artikel passend kennzeichnen","scene":"Neben den Pumpen und dem Flaschenhalter liegen L10, B80, S20 und T30 auf der Aktionsfläche.","ask":"Welche Angaben können unverändert auf das jeweilige Regalschild übernommen werden?","options":["L10: Die Halterung fürs Vorderlicht passt für Lenker mit 22 bis 32 mm Durchmesser.","B80: Das Klettband ist von 20 bis 40 cm Umfang verstellbar.","S20: Das Schloss gehört oben ins Regal, damit es am schnellsten sichtbar ist.","T30: Die Rahmentasche fasst 1,2 Liter und ist wasserabweisend.","B80: Das Band leuchtet ohne Beleuchtung selbstständig.","T30: Die Tasche ist vollständig wasserdicht."],"answer":[0,1,3],"why":"Die Maße für Lenker und Reflektorband sowie Volumen und Regenhinweis der Tasche entsprechen den Produktkarten. Das Schloss gehört nach M3 in die untere Regalzone. Das Band reflektiert auftreffendes Licht.","hint":"Schau je Aussage auf den Produktcode und den Wortlaut der Karte.","steps":"Prüfe Zahlen, Einheit und Produkteigenschaft. Achte besonders auf Wörter, die die Wirkung verstärken.","example":"Wasserabweisend und wasserdicht sind verschiedene Angaben.","c":0,"sourceRefs":["M3"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Startpunkte im Test abdecken","scene":"Übungsvariante: Eine Person beginnt den Einkauf am Zugang. Eine zweite kommt aus der Fahrradabteilung. Beide sollen Zubehör finden.","ask":"Welche Schritte liefern einen brauchbaren Vergleich der Orientierung?","options":["Beiden Personen vor dem Start die genaue Gondel zeigen.","Den Ort notieren, an dem jede Testperson den ersten Hinweis bemerkt.","Beide von ihrem vorgesehenen Startpunkt aus ohne Wegvorgabe suchen lassen.","Die zweite Person an der ersten starten lassen, damit beide immer denselben Laufweg haben.","Beide fragen, ob und wo sie das gewünschte Produkt gefunden haben.","Nur die bevorzugte Laufrichtung des Teams einzeichnen."],"answer":[1,2,4],"why":"Zwei verschiedene Ausgangspunkte zeigen, ob Hinweise aus beiden Richtungen wirken. Das Suchziel kann gleich bleiben. Beobachtung und Rückmeldung helfen, einen schwachen Hinweis zu finden.","hint":"Halte den Unterschied der Startpunkte im Test sichtbar.","steps":"Beobachte zuerst, wann ein Hinweis auffällt. Frage danach, wie die Person die Ware gefunden hat.","example":"Wer das Schild erst nach längerem Suchen entdeckt, liefert eine konkrete Stelle für die Überarbeitung.","c":2,"sourceRefs":["M2","M4","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Messwerte und Einkaufsszene gemeinsam prüfen","scene":"Übungsvariante: Das Team hat die Bedienzonen im leeren Modell vermessen. Im Rollenspiel bleibt eine Person mit Wagen stehen und liest am Rand der Aktion.","ask":"Welche weiteren Prüfungen sind sinnvoll?","options":["Ausprobieren, ob eine zweite Person an ihr vorbei zur Fahrradabteilung kommt.","Die Prüfung abbrechen, weil die Maße im leeren Modell bereits eingetragen sind.","Beobachten, ob beide langen Gondelseiten erreichbar bleiben.","Die Zeit fürs Lesen als alleinigen Nachweis der Gangbreite verwenden.","Im Plan festhalten, wo Wagen und lesende Person während der Probe stehen.","Der Testperson vorschreiben, die Karte im Laufen zu lesen."],"answer":[0,2,4],"why":"Die Praxisprobe ergänzt die Messung. Sie zeigt, wo Menschen oder Wagen beim echten Einkauf Raum beanspruchen und ob andere Wege und Bedienseiten weiter erreichbar bleiben.","hint":"Prüfe, welche Bewegungen gleichzeitig stattfinden.","steps":"Markiere die Stelle des Halts und spiele die Bewegung einer zweiten Person nach.","example":"Eine Bedienzonenbreite auf Papier zeigt die Möblierung. Ein Rollenspiel zeigt zusätzlich das Verhalten.","c":1,"sourceRefs":["M2","M4","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Gezielt nach einer Kartenrückmeldung handeln","scene":"Übungsvariante: Eine Testperson findet den Flaschenhalter und erkennt, dass er zu ihrer 74-mm-Flasche passt. Sie kann nach dem Lesen nicht sagen, was sie am Rad prüfen muss.","ask":"Welche Änderungen und Prüfungen greifen ihre Rückmeldung auf?","options":["Das Schild vom Halter entfernen, weil das Produkt schon gefunden wurde.","Auf der Karte Flaschendurchmesser und Abstand der Rahmengewinde in getrennten Zeilen zeigen.","Die Angabe „64 mm“ klar als Gewindeabstand am Fahrrad beschriften.","Das Team fragt bei einer zweiten Probe nach der Messung, die vor dem Kauf noch nötig ist.","Das Schild nur höher hängen und alle Zeilen unverändert lassen.","64 mm als Durchmesser der mitgebrachten Flasche ausweisen."],"answer":[1,2,3],"why":"Die Suche und der Flaschendurchmesser waren verständlich. Die Anpassung muss die Montagebedingung am Fahrrad hervorheben und mit einer ähnlichen Testfrage erneut geprüft werden.","hint":"Suche den Einkaufsschritt, den die Person bereits geschafft hat, und den, der noch offen ist.","steps":"Überarbeite die fehlende Zuordnung und prüfe, ob eine neue Testperson das nötige Maß nennen kann.","example":"Ein kleiner Test fragt etwa: „Welche Strecke würdest du am Fahrrad messen?“","c":2,"sourceRefs":["M2","M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen zunächst überzeugenden Aufbau überprüfen","scene":"Übungsvariante: Du bevorzugst Plan A, weil das Schild gleich zu sehen ist. Dann bemerkst du, dass sein Fuß im Hauptgang steht. In Plan B bleibt der Weg frei, aus der Fahrradabteilung ist dessen Schild aber erst spät sichtbar.","ask":"Wie gehst du mit deiner ersten Einschätzung um?","options":["Bei A bleiben, weil die Kundschaft die Aktion früh sehen soll.","A an der Wegregel prüfen und die ursprüngliche Empfehlung bei belegter Überschneidung korrigieren.","Einen neuen Hinweis für B aus der Richtung der Fahrradabteilung testen lassen.","Am eigenen Entwurf beide Startpunkte ohne Wegerklärung prüfen lassen.","Die Prüfung beenden, sobald eine Testperson vom Eingang das Schild findet.","Den Schildfuß in A nur in einer anderen Farbe in den Plan zeichnen."],"answer":[1,2,3],"why":"Frühe Sichtbarkeit allein trägt die ursprüngliche Wahl nicht. Die Wegregel bestimmt, wo das Schild stehen darf. Beide Startpunkte im nächsten Test zeigen, ob die Hinweise auch ohne Erklärung auffallen.","hint":"Trenne deinen ersten Eindruck von der überprüfbaren Wegregel.","steps":"Vergleiche die beiden Ansätze nach freiem Weg und Sichtbarkeit. Lasse den überarbeiteten Entwurf ohne Hilfe testen.","example":"Beim Test darf eine Person ihren eigenen Weg wählen, damit du siehst, welcher Hinweis tatsächlich bemerkt wird.","c":1,"sourceRefs":["M1","M2","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Entscheidung im kurzen Pitch zeigen","scene":"Übungsvariante: Die Leitung möchte in ungefähr zwei Minuten verstehen, wie die Kundschaft nun eine Pumpe ohne feste Beratung auswählen kann.","ask":"Welche Elemente sind im Pitch passend?","options":["Im Lageplan vom Zugang zur Pumpen-Gondel führen.","Die Packungsfarben aufzählen und den Ventilhinweis übergehen.","An der Vergleichskarte zeigen, wo die Kundschaft die Ventiltypen erkennt.","Eine Beobachtung nennen, die geholfen hat, Schild oder Karte zu verändern.","Nur die Überschrift des Lageplans laut vorlesen.","Den Durchgang zur Fahrradabteilung aus der Erklärung entfernen, obwohl er im geplanten Kundenlauf wichtig ist."],"answer":[0,2,4],"why":"Der Pitch verbindet Orientierung, Auswahl und einen Beleg für die Entscheidung. Die Leitung sieht, wo jemand hingeht, welche Angabe dort hilft und was die Probe über den Aufbau gezeigt hat.","hint":"Denke an den konkreten Einkauf vom ersten Hinweis bis zur Wahl am Regal.","steps":"Wähle eine Stelle im Plan, eine Produktangabe und eine Beobachtung aus.","example":"„Die Testperson hat beim ersten Versuch am falschen Regal angehalten“ ist eine nutzbare Beobachtung.","c":4,"sourceRefs":["M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ersten Probelauf vorbereiten","scene":"Übungsvariante: Kurz vor der Aktion erlaubt die Ladenleitung einen letzten Test. Eine Einkaufsspur beginnt am Zugang und führt zu den Pumpen. Die andere beginnt in der Fahrradabteilung und führt zum Flaschenhalter. Es gibt keine feste Beratung an der Fläche.","ask":"Wie startest du die Prüfung?","options":["Ich zeichne beide erwarteten Laufwege ein und markiere, wo die Personen jeweils ihren ersten Hinweis finden sollten.","Ich bitte zwei Personen, ohne Hilfestellung je eine Einkaufsrolle zu übernehmen und ihren Eindruck anschließend zu schildern.","Ich halte zuerst die freien Gänge und Bedienseiten als Prüfvorgaben fest und bestimme, wer beim Test die Wege beobachtet.","Ich markiere im Modell je einen Messpunkt für die freie Wegbreite und einen Punkt zum Lesen und nutze beide im Testprotokoll.","Ich bespreche mit dem Team, welche Rückfragen die Rollen beim Vorbeigehen und am Regal stellen dürfen, ohne ihnen den Weg vorzugeben.","Ich lege für den Test fest, wo Wagen und Testmaterial bereitstehen und welche Gänge jederzeit frei sein müssen."],"consequences":["Deine markierten Wege machen es möglich, erwarteten und beobachteten ersten Hinweis zu vergleichen.","Die Rollen liefern nachvollziehbare Eindrücke von beiden Startpunkten.","Vorgaben und Zuständigkeiten sind vor Beginn geklärt.","Messung und Beobachtung bekommen feste Bezugspunkte im Plan.","Beide Teams können Rückmeldungen sammeln, ohne den Testpersonen die Auswahl vorwegzunehmen.","Die Testmittel und die freizuhaltenden Bereiche sind vor der Probe berücksichtigt."],"why":"Die Probe prüft zwei Einkaufsrichtungen und freie Wege. Wer eigenständig einkaufen soll, braucht Hinweise, die auch ohne Erklärung wirken.","hint":"Lege den Schwerpunkt fest, mit dem du die kommenden Beobachtungen weiterverfolgst.","steps":"Entscheide, ob dein erster Schritt Daten sichert, Rückmeldungen organisiert oder Bedingungen des Tests klärt.","example":"Ein markierter Suchpunkt lässt sich im Plan zu einer späteren Beobachtung zuordnen.","c":3,"sourceRefs":["M1","M2","M5"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Einen Hinweis aus zwei Richtungen prüfen","scene":"Vom Eingang aus sieht die Testperson das Orientierungsschild. Die zweite Person sieht es aus der Fahrradabteilung erst, als sie schon an der Aktion vorbeigegangen ist.","ask":"Wie setzt du die Arbeit fort?","options":["Ich zeichne in den Plan ein, wo beide Personen das Schild zuerst bemerkt haben, und vergleiche die Sichtlinien.","Ich frage die zweite Person, wann sie den Hinweis erwartet hat, und lasse sie einen neuen Vorschlag ohne Wegvorgabe ausprobieren.","Ich prüfe, wo ein zweiter, an der Gondel befestigter Hinweis zulässig ist und ohne neuen Schildfuß montiert werden kann.","Ich fotografiere oder skizziere beide Blickrichtungen und prüfe daran, welche Seite der Gondel einen Hinweis aufnehmen kann.","Ich hole Rückmeldung von je einer Person aus beiden Laufrichtungen ein und lasse das Team daraus die sinnvollste Ausrichtung vorschlagen.","Ich plane den Standortwechsel unter der Bedingung, dass Hauptgang und Durchgang in voller Breite frei bleiben, und bestimme den Zeitpunkt für die Nachkontrolle."],"consequences":["Im Plan ist die unterschiedliche Wirkung des Schildes direkt verortet.","Die Rückmeldung benennt das Problem aus Sicht der vorbeigehenden Person und fließt in die nächste Probe ein.","Die ergänzende Befestigung wahrt die frei zu haltenden Bodenflächen.","Der Vergleich der Blickrichtungen gibt dir eine fachliche Grundlage für die Platzierung.","Die Ausrichtung berücksichtigt beide Einkaufsrichtungen.","Der Standortwechsel bleibt an die Wegregeln und einen Prüfschritt gebunden."],"why":"Ein gut sichtbares Schild kann aus einer Richtung spät auffallen. Eine weitere Beschilderung muss Wege und Bedienzonen freihalten.","hint":"Schließe an die Grundlage an, die du für den Probelauf gewählt hast.","steps":"Prüfe einen neuen Hinweis aus beiden Richtungen.","example":"Ein freier Blick aus dem Zugang sagt noch nichts über den Rückweg aus der Fahrradabteilung.","c":2,"sourceRefs":["M1","M2","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Pumpenvergleich verständlich machen","scene":"Die Person vom Eingang findet die Pumpen. Auf der bisherigen Karte übersieht sie, dass beide Pumpen zum Autoventil passen. Sie erkennt auch schwer, welche Pumpe eine Druckanzeige hat.","ask":"Wie verbesserst du die Karte mit deinem bisherigen Schwerpunkt?","options":["Ich vergleiche die Karte mit M3 und markiere in einer Tabelle getrennt, was bei Ventilart und Druckanzeige bei P50 und P51 steht.","Ich frage, an welcher Stelle die Person die Angaben erwartet, und lasse sie zwei Kartenentwürfe kommentieren.","Ich lege fest, dass die Karte direkt an der Pumpengondel lesbar angebracht wird und keine Halterung in die Bedienzone ragt.","Ich halte fest, welche Zeile in der Probe übersehen wurde, und prüfe anhand der Produktkarte die neuen, gleich aufgebauten Spalten.","Ich lasse zwei Personen anhand der überarbeiteten Karte die passende Pumpe für unterschiedliche Zwecke wählen und hole ihre Begründungen ein.","Ich vereinbare, wer beide Produktdaten kontrolliert und die geprüfte Karte an der vorgesehenen Seite befestigt."],"consequences":["Die neue Karte stützt sich auf die Produktdaten und zeigt die Gemeinsamkeit und den Unterschied klar.","Die Rückmeldungen helfen, die entscheidenden Zeilen an einem erwartbaren Ort anzuordnen.","Die Karte unterstützt die Auswahl direkt am Regal und lässt den Zugriff frei.","Die Überarbeitung reagiert auf einen belegten Lesefehler und lässt sich erneut überprüfen.","Du erfährst, ob verschiedene Einkaufsbedürfnisse mit derselben Karte verstanden werden.","Datenprüfung und Anbringung sind geklärt, bevor die Karte eingesetzt wird."],"why":"Beide Pumpen passen zum Autoventil. Die Standpumpe hat ein Manometer. Platzierung, Vergleichbarkeit und Datenrichtigkeit unterstützen die Wahl.","hint":"Greife den Schwerpunkt deiner bisherigen Schritte auf.","steps":"Ordne die Rückmeldung der fehlenden oder schlecht auffindbaren Kartenzeile zu.","example":"Eine gemeinsame Zeile „Ventile“ erleichtert den Vergleich zweier passender Modelle.","c":4,"sourceRefs":["M2","M3","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Flaschenhalter selbstständig auswählen","scene":"Die Person aus der Fahrradabteilung findet F60. Ihre Flasche misst 74 mm. Beide Rahmengewinde sind sichtbar, ihr Abstand ist unbekannt. Die Testperson liest die Maßangaben auf eurer Karte.","ask":"Wie stellst du sicher, dass sie vor dem Kauf die richtige Prüfung vornimmt?","options":["Ich überprüfe beide Maßangaben anhand von M3 und zeige getrennt, welche Angabe bereits erfüllt ist und was offen bleibt.","Ich frage die Testperson, was sie an ihrer Flasche weiß und was sie am Fahrrad noch messen würde, und passe die Karte bei Bedarf an.","Ich lege fest, dass die beiden Anforderungen auf der Karte unabhängig voneinander gelesen werden können, und vereinbare vor dem Aufbau eine Prüfung der Beschriftung.","Ich notiere den im Test genannten Gewindeabstand und prüfe anhand der Produktkarte, ob die nötige Rahmenmessung erkannt wurde.","Ich lasse eine zweite Person die Karte lesen und danach in eigenen Worten erklären, wo sie Maß nehmen würde.","Ich halte als Freigabebedingung fest, dass ein Teammitglied die getrennt ausgewiesenen Angaben zur Flasche und Rahmenmontage prüft."],"consequences":["Die Karte trennt die belegte Flaschenpassung von der offenen Montagefrage.","Die Testperson macht klar, ob die Karte schon zum richtigen nächsten Handlungsschritt führt.","Die getrennte Darstellung und ihre Kontrolle sind vor dem Öffnen verbindlich vorgesehen.","Du kannst anhand der beobachteten Antwort prüfen, ob die Montagebedingung verstanden wurde.","Eine unabhängige Rückmeldung zeigt, ob der Montagehinweis auch ohne Vorkenntnisse verständlich ist.","Es ist klar, wer die Vergleichsangaben vor dem Einsatz überprüft."],"why":"74 mm liegen im erlaubten Bereich für die Flasche. Am Fahrrad müssen die zwei passenden Rahmengewinde 64 mm auseinanderliegen. Ihre Sichtbarkeit allein reicht für die Entscheidung noch nicht aus.","hint":"Frage nach Flaschendurchmesser und Rahmenabstand getrennt.","steps":"Kläre, welcher Vergleich bereits möglich ist und welche Messung noch fehlt.","example":"Eine Person kann die richtige Flasche vorzeigen und die Montagefrage erst zu Hause prüfen.","c":0,"sourceRefs":["M2","M3","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Beim Lesen Raum für den Einkauf lassen","scene":"Nach der Anpassung werden Pumpen- und Flaschenhalterkarte gut gefunden. Während eine Person mit Wagen die Pumpe vergleicht, weicht eine zweite auf dem Weg zur Fahrradabteilung aus.","ask":"Was tust du vor der Freigabe?","options":["Ich markiere den Halt des Wagens und kontrolliere im Modell die nutzbare Durchgangsbreite an diesem Punkt.","Ich lasse beide Rollen beschreiben, wo das Lesen oder Vorbeigehen schwierig wurde, und probiere mit ihnen eine kleine Anpassung aus.","Ich suche einen Lesepunkt innerhalb der Aktionsfläche, bei dem der Hauptgang und die Bedienzonen frei bleiben können, und ordne einen neuen Probelauf an.","Ich dokumentiere die Beobachtung vor und nach einer veränderten Kartenposition und vergleiche die beiden Wege.","Ich lasse Testpersonen mit und ohne Wagen an der geänderten Stelle vergleichen und frage danach, was sich für sie verändert hat.","Ich entscheide nach den Flächenregeln, welche Schildpositionen infrage kommen, und bestimme, wer die Abstände beim Aufbau misst."],"consequences":["Die Engstelle wird im Plan überprüfbar.","Die Anpassung berücksichtigt sowohl das Lesen als auch das Vorbeigehen.","Freie Wege bleiben feste Bedingungen bei der Suche nach einer Alternative.","Ein kontrollierter Vergleich zeigt, ob die Änderung den beobachteten Konflikt tatsächlich löst.","Die Rückmeldungen prüfen die Nutzbarkeit für zwei unterschiedliche Einkaufsabläufe.","Jemand kann kontrollieren, ob der gewählte Standort in der wirklichen Fläche die Vorgaben einhält."],"why":"Selbstständige Auswahl braucht lesbare Angaben und Platz zum Stehen. Die Beobachtung aus dem Probelauf ergänzt die gemessenen Breiten.","hint":"Behalte deinen bisherigen Prüfweg bei und richte ihn auf die Stelle, an der jemand ausweicht.","steps":"Prüfe gleichzeitig Leseposition, Wagen und vorbeigehende Person.","example":"Eine verschobene Karte kann auch den Punkt verändern, an dem die Kundschaft anhält.","c":1,"sourceRefs":["M1","M2","M4","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Aufbau begründet übergeben","scene":"Die Leitung bittet nach dem Probelauf um den aktualisierten Flächenplan, die Schilder und die Vergleichskarten. Sie möchte auch wissen, was beim wirklichen Aufbau noch geprüft wird.","ask":"Wie stellst du deinen fertigen Arbeitsweg vor?","options":["Ich zeige zwei konkrete Beobachtungen, die zu geänderten Hinweisen oder Wegen geführt haben, und benenne eine offene Kontrolle vor Ort.","Ich zeige, wie Rückmeldungen aus beiden Einkaufsrollen in Aufbau und Karten eingeflossen sind, und vereinbare eine Rückmeldung nach der Aufbauprobe.","Ich übergebe einen beschrifteten Aufbauplan mit freien Flächen und lege fest, wer Wege, Abstände und Karten vor dem Start prüft.","Ich verknüpfe die markierte Engstelle mit meinem Vorher-Nachher-Vergleich und zeige, wie sich die Auswahl an den Karten im Probelauf überprüfen ließ.","Ich benenne, welche Rückmeldung zur Orientierung und welche zum Vergleichen geführt hat, und erkläre, wer die Umsetzung erneut ausprobieren soll.","Ich ordne die restlichen Arbeiten nach Aufbau, Kontrolle der Wege und Freigabe der Karten und markiere die Verantwortlichen im Plan."],"consequences":["Die Leitung kann prüfen, auf welche Beobachtungen sich deine Änderungen stützen.","Die Leitung sieht, welche Erfahrungen Betroffener in der Fassung berücksichtigt sind.","Die Übergabe macht die Bedingungen und Verantwortlichkeiten des echten Aufbaus sichtbar.","Dein Vergleich verbindet Flächenplan, Einkaufstest und fachliche Änderungen.","Die Rückmeldungen bleiben im Weiterarbeiten nutzbar und die erneute Probe ist konkret.","Der Aufbau kann mit klarer Reihenfolge und zugeordneten Prüfungen erfolgen."],"why":"Eine überzeugende Übergabe zeigt den Weg, die Vergleichsinformationen und den Nachweis der Verbesserung. Der wirkliche Aufbau bietet Gelegenheit für die letzte Kontrolle.","hint":"Schließe mit dem Schwerpunkt ab, den du bei der ersten Entscheidung gewählt hast.","steps":"Verknüpfe die Empfehlungen mit deinem Plan und einem überprüfbaren nächsten Schritt.","example":"Eine noch ausstehende Kontrolle gehört als offene Aufgabe erkennbar in die Übergabe.","c":4,"sourceRefs":["M1","M3","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Erster Blick auf die Aktion","scene":"Sarah sagt, dass Familien die Aktion sehen sollen, bevor sie zur Fahrradabteilung gehen.","ask":"Welche Angaben passen dazu?","options":["Sarah arbeitet im Marketing.","Sarah achtet auf die frühe Sichtbarkeit für Familien.","Der Hinweis soll erst nach dem Einkauf bemerkt werden.","Sarah will alle Pumpen an der Kasse erklären.","Sarah plant den Ort für ein Vorführrad.","Sarah legt die Gewindeabstände der Halter fest."],"answer":[0,1],"why":"Sarah betrachtet die Aktion aus Sicht des Marketings und achtet auf den ersten Blick.","hint":"Achte auf die Zielgruppe und ihren Weg.","steps":"Verbinde Sarahs Aufgabe mit dem gewünschten Zeitpunkt.","example":"Ein Schild kann früh auf Zubehör hinweisen, auch wenn die Ware etwas weiter entfernt steht.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Zwei Vorschläge prüfen","scene":"Übungsvariante: Sarah schlägt einen gut sichtbaren Hinweis beim Zugang vor. Sebastian beobachtet, wie jemand genau dort mit Wagen zum Lesen anhält.","ask":"Welche Prüffragen greifen beide Sichtweisen auf?","options":["Ist das Schild vom Zugang aus erkennbar?","Kann jemand am Schild lesen, während andere weitergehen?","Kann Sebastian ab Samstag fest am Schild beraten?","Welche Preisfarbe bringt Sarah auf die Pumpenpackung?","Bleibt der Durchgang beim Anhalten vollständig nutzbar?","Kann die Aktionsfläche erst hinter der Fahrradabteilung beginnen, ohne Sichtbarkeit zu prüfen?"],"answer":[0,1,4],"why":"Die Wünsche betreffen Sichtbarkeit und Platz. Beides lässt sich beim Gehen und Halten prüfen.","hint":"Woran würde Sarah Erfolg erkennen? Woran Sebastian?","steps":"Prüfe zuerst Finden, dann Nutzung beim Stehenbleiben.","example":"Die gute Sichtbarkeit einer Karte sagt noch nichts über die freie Breite am Lesepunkt.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2"]},{"title":"Einen Einkaufsschritt beschreiben","scene":"Der Vater dreht eine Pumpenpackung um. Der Sohn möchte wissen, welche Pumpe zum Kinderfahrrad passt.","ask":"Was zeigt die Beobachtung unmittelbar?","options":["Der Vater sucht auf der Rückseite der Verpackung.","Der Sohn fragt, welche Pumpe zum Kinderfahrrad passt.","Der Vater hat schon eine Pumpe gekauft.","Der Sohn prüft den Flaschendurchmesser.","Die Pumpen konnten am platzfesten Tresen vorgeführt werden.","Die Kundschaft sucht den Weg zur Kasse."],"answer":[0,1],"why":"Der Vater dreht die Packung um und der Sohn fragt nach der Passung. Diese beiden Beobachtungen kannst du festhalten. Ob sie später etwas kaufen, bleibt offen.","hint":"Trenne Beobachtung und Vermutung.","steps":"Achte darauf, was der Vater tut und was der Sohn wissen möchte.","example":"Das Umdrehen einer Packung ist beobachtbar. Ein späterer Kauf ist eine andere Frage.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2","M5"]},{"title":"Aus der Sicht der wartenden Person prüfen","scene":"Übungsvariante: Eine Testperson liest die Pumpeninfos, ihr Wagen steht dabei am Gang. Jemand auf dem Weg zur Fahrradabteilung muss warten.","ask":"Welche Beobachtungen sollte dein Entwurf künftig aufnehmen?","options":["Wo Wagen und lesende Person beim Halt stehen.","Ob der Hinweis für die lesende Person verständlich ist.","Welche Schuhe die wartende Person trägt.","Wie viele Packungen im Lager bleiben.","Ob der Weg beim Halt für eine weitere Person frei bleibt.","Ob der Wagen zur Kasse geschoben werden darf."],"answer":[0,1,4],"why":"Die Probe prüft die Auswahl und das Vorbeigehen gleichzeitig. Relevant sind Standort, Lesen und freie Bewegung.","hint":"Erinnere dich an die zweite Person in der Szene.","steps":"Betrachte die Fläche aus Sicht beider Beteiligter.","example":"Eine lesende Person braucht Zeit und Platz. Eine vorbeigehende Person braucht einen freien Weg.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M2","M5"]},{"title":"Eine Aufgabe ohne Fragen lösen","scene":"Eine Person kommt vom Eingang, sieht den Hinweis „Zubehör“ und nimmt am Regal einen passenden Artikel.","ask":"Welche Schritte sind typische Selbstbedienung?","options":["Die Fläche mithilfe des Schilds finden.","Eine Mitarbeiterin um das Herausgeben jeder Ware bitten.","Einen Artikel selbst aus dem Regal nehmen.","Die Preise im Büro erfragen müssen.","Das Schild als persönliche Beratung behandeln.","Packungen nur mit Erlaubnis aus dem Lager holen."],"answer":[0,2],"why":"In der Selbstbedienung erledigt die Kundschaft Suche und Auswahl meist selbst. Hinweise und erreichbare Regale helfen.","hint":"Achte darauf, wer jeden Schritt ausführt.","steps":"Verfolge die Folge vom Finden bis zum Greifen.","example":"Ein verständliches Schild kann den ersten Weg erklären.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5","M6"]},{"title":"Vom Finden zum Auswählen kommen","scene":"Übungsvariante: In der Aktion finden Personen den Flaschenhalter ohne Hilfe, greifen aber bei der Auswahl regelmäßig zur falschen Größe.","ask":"Welche Maßnahmen verbessern die Selbstbedienung?","options":["Die Flaschendurchmesser am Halter verständlich nennen.","Den Artikel hinter einem Tresen verwahren.","Beim Einkauf jeden Kunden zur Beratung rufen.","Den Zugang zum Warenplatz offenhalten und die Angaben dort lesbar machen.","Mit einer kurzen Probe prüfen, ob die Kundschaft anhand der Karte selbst auswählt.","Die Zubehörbeschilderung entfernen, weil das Finden schon klappt."],"answer":[0,3,4],"why":"Der Weg funktioniert bereits. Die klaren Daten direkt am Warenplatz und eine Auswahlprobe verbessern den nächsten Schritt.","hint":"Suche den Einkaufsschritt, der noch nicht gelingt.","steps":"Behalte die Orientierung und verbessere die Information beim Vergleichen.","example":"Ein Wegweiser zum Regal ersetzt keine Maßangabe am Produkt.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5","M6"]},{"title":"Weg oder Halt unterscheiden","scene":"Ein Vater schiebt seinen Wagen Richtung Aktion und hält zum Lesen an.","ask":"Welche Einträge passen in den Kundenlaufplan?","options":["Pfeil für die Richtung, in die er geht.","Punkt für den Ort des Anhaltens.","Schildpreisliste als Eintrag zum Weg.","Nur die später gekaufte Menge aufschreiben.","Warengruppe als Ersatz für einen Bewegungsweg markieren.","Den Halt als neuen Ladeneingang beschriften."],"answer":[0,1],"why":"Pfeil und Punkt beschreiben zwei verschiedene Dinge. So erkennt man Bewegungsrichtung und Lesestelle.","hint":"Wo bewegt sich der Wagen und wo bleibt er stehen?","steps":"Nutze je ein Zeichen für Bewegung und Halt.","example":"Eine Haltemarkierung kann beim späteren Standorttest helfen.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M6"]},{"title":"Zwei Bewegungen in einer Skizze darstellen","scene":"Übungsvariante: Eine Person läuft aus der Fahrradabteilung zur Aktion. Eine zweite kommt vom Eingang und hält mit einem Wagen am Rand der Gondel.","ask":"Welche Planangaben zeigen den möglichen Konflikt?","options":["Die beiden Startpunkte im Grundriss eintragen.","Nur den Gang im leeren Laden markieren.","Den Wagenhalt an der tatsächlichen Lesestelle markieren.","Den Namen der Marke an jeder Lauflinie wiederholen.","Die Stelle prüfen, an der beide Wege nahe am Halt liegen.","Beide Laufwege unabhängig von der Beobachtung gleich zeichnen."],"answer":[0,2,4],"why":"Startpunkte, Wege und Haltestelle zeigen, wo sich beide Einkaufsbewegungen stören könnten.","hint":"Beginne bei den Startpunkten der beiden Personen.","steps":"Verfolge beide Bewegungen und markiere den Wagenhalt.","example":"Ein Punkt für den Halt zeigt besser, wo ein Wagen Raum beansprucht, als ein langer Pfeil.","id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M6"]},{"title":"Vor der langen Regalseite Platz lassen","scene":"Die Artikel stehen an beiden langen Seiten der Gondel. Jeweils davor liegt eine Bedienzone.","ask":"Welche Aussagen passen zu M1?","options":["An beiden langen Seiten muss man greifen können.","Die Bedienzone ist ein Regalfach.","In der Bedienzone steht ein weiterer Warenträger.","Der Platz vor der langen Warenseite bleibt frei.","Nur die kurze Stirnseite wird auf Zugänglichkeit geprüft.","Der Zugriff ist nicht vom Hauptgang aus vorgesehen."],"answer":[0,3],"why":"Die Gondel ist beidseitig bestückt. Deshalb bleibt vor beiden langen Seiten ein erreichbarer Streifen frei.","hint":"Welche beiden Seiten tragen Ware?","steps":"Unterscheide Möbel und Bodenfläche vor dem Möbel.","example":"Wer vor dem Regal Platz braucht, nutzt die Bedienzone.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Eine zweite Seite erreichbar halten","scene":"Übungsvariante: Eine Gondel wird gedreht. Die zuerst geprüfte lange Seite ist frei. Vor der gegenüberliegenden langen Seite steht aber jetzt das zweite Regal.","ask":"Welche Korrekturen passen?","options":["Nur die erste Seite prüfen, weil sie schon markiert ist.","Die Platzierung so ändern, dass vor beiden langen Seiten freie Streifen bleiben.","Beide Seiten nach der Änderung vom Hauptgang aus erreichen können.","Die gegenüberliegende Seite mit einem Orientierungsschild als frei markieren.","Die Breite vor beiden langen Seiten im Plan kontrollieren.","Das blockierende Möbel als Teil der Bedienzone zählen."],"answer":[1,2,4],"why":"Beide Regalseiten sind ein Teil der Selbstbedienung. Drehung und Verschieben müssen ihre freien Zonen und den Zugang vom Hauptgang erhalten.","hint":"Stell dich im Gedanken vor jede lange Seite.","steps":"Prüfe erst freien Boden, dann den Weg vom Gang dorthin.","example":"Eine zugängliche erste Seite kann die blockierte zweite nicht ersetzen.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Einer Frage die richtige Information geben","scene":"Ein Kunde fragt: „Wo finde ich die Pumpen?“ Am richtigen Regal möchte er danach die Ventilart prüfen.","ask":"Welche Informationen passen?","options":["Ein Wegweiser „Pumpen“ führt zum Regal.","Das Pumpenmodell auf der Produktkarte zeigt, wo der Eingang liegt.","Die passenden Ventiltypen gehören auf die Regalkarte.","Ein Foto vom Eingang ersetzt die Ventilangabe.","Der Preis benennt den Ventiltyp.","Eine Pumpe im Regal gibt als solche die Laufrichtung vom Eingang an."],"answer":[0,2],"why":"Ein Wegweiser unterstützt das Finden. Die Ventiltypen helfen erst am Regal bei der Produktauswahl.","hint":"Wer sucht wohin und wer vergleicht was?","steps":"Trenne Ziel im Laden und Produktmerkmal.","example":"„Zubehör →“ ist ein Wegweiser. „Passt für Autoventil“ ist ein Produktmerkmal.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5","M6"]},{"title":"Von der Fahrradabteilung zum Zubehör führen","scene":"Übungsvariante: Eine Person kommt aus der Fahrradabteilung und sucht F60. Nach dem Finden möchte sie den Halter zur vorhandenen Flasche zuordnen.","ask":"Wie verteilt ihr die Informationen auf Schild und Karte?","options":["Die Richtung zur Zubehörfläche am Abzweig zeigen.","Am Abzweig allein den Gewindeabstand 64 mm nennen.","Den zulässigen Flaschendurchmesser am Warenplatz angeben.","Am Warenplatz nur die Richtung zum Eingang zeigen.","Den Rahmenabstand getrennt vom Flaschendurchmesser erklären.","Ein bloßes Logo als vollständige Montageinformation verwenden."],"answer":[0,2,4],"why":"Das Richtungsschild löst das Finden. Die Karte am Halter erklärt die Eignung für Flasche und Montage getrennt.","hint":"Überlege, an welcher Station jede Frage entsteht.","steps":"Platziere den Weghinweis vor dem Warenplatz und die Maße beim Artikel.","example":"Eine Montageangabe hilft erst, wenn sie dem richtigen Artikel zugeordnet ist.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5","M6"]},{"title":"Welche Pumpe hat eine Druckanzeige?","scene":"P50 und P51 haben ähnliche Verpackungen. P50 ist klein und für unterwegs gedacht. P51 ist eine Standpumpe mit Manometer.","ask":"Welche Aussagen stimmen?","options":["Das Manometer zeigt den Druck an.","P50 ist die große Standpumpe.","P51 kann eine Druckanzeige bieten.","P50 und P51 gehören deshalb zu verschiedenen Warengruppen.","P50 wird in der Karte mit Druckanzeige angegeben.","Die Begriffe Minipumpe und Standpumpe bezeichnen hier denselben Artikelcode."],"answer":[0,2],"why":"P51 hat ein Manometer. Die unterschiedlichen Pumpen sind dennoch in derselben Warengruppe.","hint":"Beachte das Wort Manometer und seine Funktion.","steps":"Vergleiche das jeweilige Modell mit seiner Ausstattung.","example":"Auch mit unterschiedlichen Größen erfüllen zwei Pumpen einen ähnlichen Zweck.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M6"]},{"title":"Eine Warengruppe zusammenstellen","scene":"Übungsvariante: Auf dem Etikett „Pumpen“ stehen P50 und P51. Die Karte soll zeigen, welches Modell zum Mitnehmen und welches für eine Druckanzeige geeignet ist.","ask":"Welche Angaben gehören dazu?","options":["P50: 18 cm, für unterwegs.","P51: 62 cm, mit Manometer.","P51: Teil der Warengruppe Flaschenhalter.","P50: ausschließlich für die Werkstatt geeignet.","Beide stehen zum Vergleich in derselben Warengruppe.","Für beide Modelle die gleiche Druckanzeige angeben."],"answer":[0,1,4],"why":"Die Warengruppe bündelt die Pumpen. Die Karte unterscheidet Merkmale, die beim Kauf eine Rolle spielen.","hint":"Suche das gemeinsame Ziel und zwei unterschiedliche Merkmale.","steps":"Ordne Einsatz, Länge und Anzeige den Artikelcodes richtig zu.","example":"Beim Vergleichen dürfen gleiche Warengruppen verschiedene Ausstattungen enthalten.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M6"]},{"title":"Zwei verschiedene Maße unterscheiden","scene":"Für F60 stehen zwei Angaben auf der Karte: 72–75 mm für die Flasche und 64 mm für den Gewindeabstand am Rahmen.","ask":"Welche Aussagen sind richtig?","options":["Die Flasche wird nach ihrem Durchmesser geprüft.","Der Gewindeabstand wird am Fahrrad geprüft.","64 mm ist die untere Grenze des Flaschendurchmessers.","72–75 mm ist der Abstand zwischen den Schrauben.","Zwei sichtbare Gewinde passen bei jedem Abstand.","Der Flaschendurchmesser wird beim Fahrradrahmen gemessen."],"answer":[0,1],"why":"Die beiden Angaben betreffen unterschiedliche Gegenstände: Flasche und Fahrradrahmen.","hint":"Woran wird das jeweilige Maß gemessen?","steps":"Markiere in jedem Eintrag die Zahl und den Gegenstand.","example":"Eine passende Flasche allein weist noch keine passende Montage nach.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M6"]},{"title":"Flasche und Befestigung getrennt beurteilen","scene":"Übungsvariante: Eine Kundin hat eine 73-mm-Flasche. Am Rad misst sie genau 64 mm zwischen zwei passenden Rahmengewinden.","ask":"Welche Aussagen passen zu den beiden Messungen und zur Produktkarte?","options":["Die Flasche liegt im vorgesehenen Durchmesserbereich.","Der gemessene Gewindeabstand passt zur Vorgabe.","Die Flasche ist zu schmal, weil sie weniger als 75 mm misst.","Die Halterung benötigt 73 mm Gewindeabstand.","Ein passender Flaschendurchmesser würde den Gewindeabstand in jedem anderen Fall ebenfalls bestätigen.","Die passenden Befestigungsschrauben liegen dem Halter bei."],"answer":[0,1,5],"why":"73 mm liegt zwischen 72 und 75 mm. Die 64 mm beziehen sich auf die Befestigung. Laut Karte sind Schrauben dabei.","hint":"Vergleiche jede Messung mit ihrer eigenen Vorgabe.","steps":"Erst die Flasche, dann den Rahmen prüfen.","example":"Ein Bereich schließt auch Werte zwischen seinen beiden angegebenen Grenzen ein.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M6"]},{"title":"Hauptgang und Aktionsfläche trennen","scene":"Der Hauptgang liegt von y = 0,00 bis y = 1,50 m. Die Aktion beginnt oberhalb und westlich des Weges zur Fahrradabteilung.","ask":"Welche Flächenzuordnungen stimmen?","options":["Der Hauptgang verläuft im unteren Streifen des Plans.","Der Schildfuß darf überall im Hauptgang stehen.","Die Aktion liegt oberhalb des Hauptgangs und westlich des östlichen Weges.","Der ganze Grundriss ist eine einzige freie Gondelfläche.","Die Aktion liegt ausschließlich im östlichen Durchgang.","Der Hauptgang muss nur am Eingang frei sein."],"answer":[0,2],"why":"Der untere Streifen bleibt als Hauptgang frei. Die Aktion liegt in einem getrennten, westlich begrenzten Bereich.","hint":"Achte zuerst auf y für unten oder oben.","steps":"Lies dann im Plan, wo westlich und östlich liegen.","example":"Verschiedene Flächen können an derselben Linie beginnen.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Eine freie Linie für den Weg lesbar halten","scene":"Übungsvariante: Dein Team soll auf einer Kopie von M1 zeigen, wo der Weg zur Fahrradabteilung und die Aktion voneinander getrennt bleiben.","ask":"Welche Einträge stimmen?","options":["Den östlichen Streifen oberhalb des Hauptgangs zwischen x = 6,40 m und x = 8,00 m freihalten.","Die Gondeln quer über die Linie x = 6,40 m schieben, weil dort die Abteilung in der Nähe ist.","Die Grenze der Aktion bei x = 6,40 m markieren.","Den Hauptgang unterhalb von y = 1,50 m in seiner Breite frei lassen.","Den östlichen Weg als Erweiterung für die Vergleichskarten einzeichnen, auch wenn der Fuß dort steht.","Nur den direkten Zugang aus der Abteilung als frei markieren."],"answer":[0,2,3],"why":"Der Hauptgang und der östliche Weg sind eigene Freiflächen. Die Gondeln bleiben mit ihren Stellflächen in der Aktionsfläche.","hint":"Beachte den x-Wert der östlichen Grenze und den y-Wert des Hauptgangs.","steps":"Trage die beiden Freistreifen vor der Möblierung ein.","example":"Ein sichtbarer Rand hilft, später keine Möbel versehentlich über die Grenze zu zeichnen.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Gleiche Merkmale für beide Pumpen","scene":"Ihr gestaltet eine Tabelle am Pumpenregal. Die Produkte sollen in zwei Spalten stehen.","ask":"Welche Zeilen helfen direkt bei der Auswahl?","options":["„Passende Ventile“ in beiden Spalten.","Bei P50 nur das Foto, bei P51 nur die Artikelnummer.","„Druckanzeige“ in beiden Spalten.","Die Öffnungszeit des Ladens in jeder Produktspalte.","Nur bei einer Pumpe eine Produktbezeichnung eintragen.","„Einsatz“ in beiden Spalten."],"answer":[0,2,5],"why":"Dieselben Merkmale ermöglichen einen Blickvergleich. Die tatsächlichen Werte dürfen je Pumpe unterschiedlich sein.","hint":"Welche Fragen stellt man zu beiden Pumpen?","steps":"Wähle je eine Zeile für Kompatibilität, Ausstattung und Einsatz.","example":"Zwei gleich benannte Zeilen verhindern, dass die Kundschaft Merkmale suchen muss.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Eine verwirrende Vergleichskarte verbessern","scene":"Übungsvariante: Auf der neuen Karte stehen links „Auto/Sclaverand“ und rechts „62 cm, Druckanzeige“. Eine Person kann daraus nicht ersehen, welche Ventile die Standpumpe nutzt.","ask":"Wie korrigiert das Team die Karte?","options":["Für beide Pumpen dieselbe Zeile „Ventile“ eintragen.","Die Ventilangaben wieder nur auf den Verpackungen zeigen.","In der Zeile „Druckanzeige“ den Unterschied für beide Pumpen nennen.","Eine fehlende Information bei der Standpumpe durch ein größeres Logo ausgleichen.","Die P50- und P51-Spalten eindeutig kennzeichnen.","Die Spalten vertauschen, die verschiedenen Zeilen aber beibehalten."],"answer":[0,2,4],"why":"Jede Pumpenspalte braucht vergleichbare Zeilen und die richtige Produktbezeichnung. So lässt sich kein Merkmal versehentlich der anderen Pumpe zuordnen.","hint":"Suche, wo Merkmale unterschiedlicher Art nebeneinander stehen.","steps":"Gleiche die Kategorien der beiden Spalten an.","example":"Eine Überschrift zeigt, welches Produkt gemeint ist; eine Zeile zeigt, welches Merkmal verglichen wird.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Einen Suchtest ohne Erklärung beginnen","scene":"Du kennst den Plan. Eine Person kommt zum ersten Mal aus dem Eingangsbereich und soll die Pumpen finden.","ask":"Welche Vorgehensweise prüft die Orientierung?","options":["Nur das Einkaufsziel nennen.","Die Gondel vorab zeigen.","Beobachten, wo der erste Hinweis auffällt.","Die Richtung vor dem Start vorlesen.","Die Person in der richtigen Bedienzone starten lassen.","Nur auf die Meinung des zeichnenden Teams hören."],"answer":[0,2],"why":"Wenn die Testperson ohne Wegangabe startet, zeigt sie, wie gut sich der Aufbau selbst erklärt.","hint":"Was darf die Person vor dem Start wissen?","steps":"Gib das Ziel und beobachte den Weg.","example":"Der erste bemerkte Hinweis ist hilfreicher als die bloße Aussage „Sie ist angekommen“.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Die eigene Erwartung nach einem Test prüfen","scene":"Übungsvariante: Dein Team erwartet, dass der seitliche Hinweis sofort auffällt. Eine Person aus der Fahrradabteilung läuft daran vorbei und findet erst später das Pumpenregal.","ask":"Welche Rückschlüsse sind begründet?","options":["Den ersten bemerkten Hinweis im Plan markieren.","An der Erwartung festhalten, weil der Hinweis groß genug wirkt.","Die Verständlichkeit aus der zweiten Richtung prüfen.","Den nächsten Testpersonen den Standort verraten, damit alle dasselbe tun.","Einen veränderten Hinweis ohne Wegerklärung erneut ausprobieren.","Das spätere Auffinden als Beleg dafür werten, dass der ursprüngliche Hinweis früh wirkte."],"answer":[0,2,4],"why":"Die Beobachtung kann die eigene Erwartung korrigieren. Anpassung und Wiederholungstest prüfen, ob sich die Orientierung verbessert.","hint":"Trenne die eigene Erwartung vom beobachteten Verlauf.","steps":"Markiere den ersten Hinweis und teste eine Änderung von derselben Startseite.","example":"Ein gefundenes Regal zeigt nicht, wann oder durch welches Schild es gefunden wurde.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Eine unklare Karte genauer besprechen","scene":"Die Testperson sagt: „Ich erkenne nicht, welches Feld zur großen Pumpe gehört.“","ask":"Welche Reaktionen helfen beim Verstehen der Rückmeldung?","options":["Fragen, welches Feld verwechselt wird.","Die Kritik als Wunsch nach einer neuen Pumpe behandeln.","Zurückmelden, dass es um die Verbindung von Feld und Pumpenmodell geht.","Die Karte in gleicher Form wieder aufhängen.","Die Regale drehen, ohne auf die Karte zu schauen.","Nur die Zahlen auf der Karte weiter auseinanderziehen, ohne die Ursache zu klären."],"answer":[0,2],"why":"Eine konkrete Rückfrage macht deutlich, welche Zuordnung unklar war. Das Team kann dann gezielt die Darstellung ändern.","hint":"Worauf genau bezieht sich „welches Feld“?","steps":"Halte fest: Welches Feld und welches Produkt?","example":"Eine eindeutige Spaltenüberschrift kann als Antwort auf die beobachtete Verwechslung dienen.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Zwei Rückmeldungen in eine Änderung übersetzen","scene":"Übungsvariante: Eine Person verwechselt P50 und P51 auf der Karte. Eine weitere versteht das Wort Manometer nicht.","ask":"Welche Änderungen helfen beiden?","options":["Die Spalten klar mit Minipumpe P50 und Standpumpe P51 beschriften.","Zusätzlich „Manometer = Druckanzeige“ erklären.","Nur die Rückmeldung der schnelleren Person übernehmen.","Die Druckanzeige der Minipumpe unzutreffend als vorhanden markieren.","Die geänderte Karte erneut ohne Erklärung lesen lassen.","Die Unterschiede beider Pumpen aus der Karte löschen."],"answer":[0,1,4],"why":"Die beiden Rückmeldungen betreffen Zuordnung und Wortverständnis. Beschriftung, kurze Worterklärung und Nachprobe lösen beide Probleme gezielt.","hint":"Sammle für jede Rückmeldung das konkrete Problem.","steps":"Passe zwei Stellen an und prüfe, ob beide verstanden werden.","example":"Mehr Schriftgröße ersetzt keine eindeutige Produktüberschrift.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Ladenmaße in Zentimeter umrechnen","scene":"Der gesamte Grundriss ist 8,00 m breit. Du zeichnest ihn im Maßstab 1:25 und trägst danach die Aktionsfläche ein.","ask":"Welche Rechenschritte stimmen?","options":["8,00 m entsprechen 800 cm.","800 cm durch 25 teilen.","800 cm mit 25 multiplizieren.","8,00 m entsprechen 80 cm.","Die Strecke auf dem Papier ist 20 cm.","Die Strecke auf dem Papier ist 32 cm."],"answer":[0,1,5],"why":"800 cm ÷ 25 ergeben 32 cm. Die Einheit im Modell muss zu den umgerechneten Zentimetern passen.","hint":"Rechne die Länge zuerst in Zentimeter um.","steps":"Teile das Wirklichkeitsmaß durch den Maßstabsfaktor.","example":"250 cm im Laden entsprechen hier 10 cm auf dem Papier.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Freie Streifen im Modell vergleichen","scene":"Übungsvariante: Eine Kontrollskizze markiert 1,50 m Hauptgang und 1,60 m Breite des östlichen Durchgangs. Sie nutzt 1:25.","ask":"Welche Aussagen sind richtig?","options":["Der Hauptgang ist im Plan 6 cm breit.","Der östliche Durchgang ist im Plan 6,4 cm breit.","Beide Streifen haben im Plan dieselbe Breite.","Die Skizze zeigt 10 cm Unterschied in der Papierbreite.","Die wirklichen 10 cm Unterschied ergeben im Plan 0,4 cm.","Für den Hauptgang braucht es 3,75 cm Planbreite."],"answer":[0,1,4],"why":"150 ÷ 25 = 6 cm. 160 ÷ 25 = 6,4 cm. Die Plandifferenz beträgt 0,4 cm.","hint":"Arbeite mit 150 cm und 160 cm.","steps":"Berechne die beiden Breiten und vergleiche erst dann.","example":"25 cm Unterschied in der Wirklichkeit ergäben 1 cm im Modell.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Einen Schildfuß zuschneiden","scene":"Der quadratische Schildfuß ist 40 cm breit und 40 cm tief. Im Modell gilt 1:25.","ask":"Welche Aussagen passen?","options":["Beide Seiten ergeben 1,6 cm im Modell.","Nur eine Seite muss durch 25 geteilt werden.","Das Modellstück bleibt quadratisch.","40 cm ergeben auf dem Modell 4,0 cm.","Die Dicke des Papiers bestimmt die Modellbreite.","Die Skizze muss 40 cm je Seite zeigen."],"answer":[0,2],"why":"Beide Seiten werden gleich verkleinert. Aus 40 cm werden 1,6 cm.","hint":"Bei einem Quadrat sind beide Seiten gleich lang.","steps":"Wende den Maßstab auf Breite und Tiefe an.","example":"20 cm im Laden würden bei 1:25 zu 0,8 cm im Modell.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Gondelmodell und freie Bedienseite gemeinsam prüfen","scene":"Übungsvariante: Das Team hat eine Gondel von 6,4 cm × 2,4 cm ausgeschnitten und davor 4,6 cm freigehalten. Der Maßstab ist 1:25.","ask":"Welche Prüfergebnisse stimmen?","options":["Die Gondel entspricht 1,60 m × 0,60 m.","4,6 cm entsprechen 1,15 m.","Für die verlangte Bedienzone fehlen 5 cm im Laden.","Die Bedienzone hat bereits 1,20 m.","Ein größeres Regaletikett könnte die Breitenvorgabe ersetzen.","Das Gondelmodell soll ursprünglich 4,8 cm × 1,20 cm messen."],"answer":[0,1,2],"why":"Die Gondel ist maßstäblich. 4,6 cm × 25 = 115 cm. Die Bedienzone soll 120 cm frei sein, also fehlen 5 cm.","hint":"Rechne Modellmaße mit 25 in echte Zentimeter zurück.","steps":"Prüfe Möbel und freien Streifen getrennt.","example":"Ein korrektes Regalmuster belegt nicht die Breite der Fläche davor.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M4"]},{"title":"Eine Regalkante mit der Grenze vergleichen","scene":"Übungsvariante: Die Grenze zum östlichen Durchgang ist x = 6,40 m. Die rechte Gondelkante liegt bei x = 6,55 m und oberhalb des Hauptgangs.","ask":"Welche Aussagen treffen zu?","options":["Die Gondel reicht in den östlichen Durchgang.","Die Gondel ragt genau 0,15 m über die Grenze.","Die Kante ist 0,15 m von der Grenze entfernt und liegt vollständig auf der Aktionsfläche.","Die zugehörige Regel betrifft nur den Haupteingang.","Der Durchgang ist durch die Farbe des Plans frei.","Das Regal kann stehen bleiben, wenn die Gondel sichtbar genug ist."],"answer":[0,1],"why":"6,55 m ist 0,15 m weiter östlich als 6,40 m. Der Durchgang muss in seiner gesamten Breite frei bleiben.","hint":"Vergleiche rechte Kante und feste Grenze.","steps":"Ziehe 6,40 von 6,55 ab und ordne die Richtung zu.","example":"Ein Regal kann nur teilweise über die Grenze reichen und sie trotzdem verletzen.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Mehr als nur die Grenze prüfen","scene":"Übungsvariante: Eine Gondel steht nach dem Verschieben vollständig westlich von x = 6,40 m. Ihre lange Warenseite ist jetzt aber vom Hauptgang aus nur über die andere Gondel erreichbar, die im Weg steht.","ask":"Welches Vorgehen ist fachlich richtig?","options":["Den behobenen Eingriff in den östlichen Durchgang festhalten.","Den Aufbau ohne weitere Prüfung freigeben.","Eine Stellung suchen, in der die Bedienseite erreichbar ist.","Nach jeder Änderung Durchgang und Bedienseiten erneut kontrollieren.","Die andere Gondel als Teil des Kundenwegs bezeichnen und nichts verändern.","Die lange Seite nicht mehr bestücken, ohne die Vorgabe an beide Seiten zu prüfen."],"answer":[0,2,3],"why":"Möbelstandort und Erreichbarkeit müssen getrennt geprüft werden. Die korrigierte Grenze allein macht den Entwurf nicht fertig.","hint":"Welche Regel gilt für jede lange Seite?","steps":"Prüfe erst die Stellfläche, dann den Weg vom Hauptgang.","example":"Ein freier äußerer Durchgang beweist keinen freien Zugang ins Innere der Aktionsfläche.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Die verbleibende Bedienzone berechnen","scene":"Übungsvariante: Ein Schildfuß belegt quer zur Bedienzone 0,10 m. Der eingezeichnete freie Streifen wäre ohne Fuß 1,20 m breit.","ask":"Welche Werte stimmen?","options":["Mit Fuß bleiben dort 1,10 m frei.","Mit Fuß bleiben 1,30 m frei.","Es fehlen dort 10 cm zum Mindestmaß.","Das eingezeichnete Maß 1,20 m bleibt auch vor dem Fuß nutzbar.","0,10 m sind 1 cm.","Der Fuß zählt als Teil der freien Zone, weil er klein ist."],"answer":[0,2],"why":"Von 1,20 m bleiben am Fuß 1,10 m. Das sind 10 cm unter der Vorgabe. In der Bedienzone steht kein Schildfuß.","hint":"Ziehe die belegte Breite ab.","steps":"Vergleiche die tatsächlich nutzbare Breite mit 1,20 m.","example":"Eine gezeichnete Fläche kann durch ein Möbel teilweise belegt sein.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M5"]},{"title":"Ein Schild versetzen und neu prüfen","scene":"Übungsvariante: Das Schild steht vollständig außerhalb des Hauptgangs, aber sein Fuß liegt vor der langen Warenseite. Ohne Schild wäre die Bedienzone frei.","ask":"Welche Lösungen sind begründet?","options":["Den Fuß auf der Aktionsfläche außerhalb der Bedienzone platzieren.","Das Schild in den Hauptgang versetzen, wo es gut sichtbar ist.","Ein geeignetes kleines Hinweisschild an der Gondel befestigen und seine Sichtbarkeit testen.","Den Fuß lassen und nur das Regal gut ausleuchten.","Nach dem Umbau Erreichbarkeit und Lesbarkeit erneut prüfen.","Die Bedienzone verkleinern, solange der Gang frei ist."],"answer":[0,2,4],"why":"Die Bedienzone bleibt vollständig frei. Eine andere Position oder Befestigung kann den Hinweis nutzbar halten.","hint":"Suche eine Lösung ohne Hindernis am Boden vor der Warenseite.","steps":"Prüfe die neue Platzierung räumlich und aus Sicht der Kundschaft.","example":"Ein Hinweis ohne Schildfuß beseitigt diese Art von Hindernis.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M5"]},{"title":"Zwei Modelle am Sclaverandventil prüfen","scene":"Eine Person fragt, welche Pumpe zu ihrem Sclaverandventil passt. Die Produktkarten sind griffbereit.","ask":"Welche Aussagen treffen zu?","options":["P50 passt zum Sclaverandventil.","P51 passt zum Sclaverandventil.","Nur die Standpumpe passt zu jedem Ventiltyp.","P50 passt allein ans Autoventil.","Eine vorhandene Druckanzeige entscheidet darüber, ob der Kopf ans Ventil passt.","Die Ventilart lässt sich nur aus der Größenangabe ablesen."],"answer":[0,1],"why":"Beide Pumpen passen laut M3 zum Sclaverandventil. Die Druckanzeige ist eine eigene Eigenschaft.","hint":"Lies bei beiden Modellen die Zeile zum Pumpenkopf.","steps":"Trenne Kompatibilität und Ausstattung.","example":"Zwei Pumpen können dasselbe Ventil bedienen und unterschiedlich ausgestattet sein.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Für die Druckkontrolle auswählen","scene":"Übungsvariante: Eine Person mit Sclaverandventil will in ihrer Garage den Reifendruck ablesen. Sie muss die Pumpe nicht in eine Tasche packen.","ask":"Welche Auswahl ist nachvollziehbar?","options":["P51 ist naheliegend, weil sie ein Manometer hat.","P50 ist besser, weil jede 18-cm-Pumpe den Druck anzeigt.","Beide Modelle passen zum angegebenen Ventil.","Die Eignung der Pumpe für die Garage bestimmt ihre Ventilart.","P50 ist für unterwegs gedacht und hat keine Druckanzeige.","Die Standpumpe ist ungeeignet, weil sie größer als P50 ist."],"answer":[0,2,4],"why":"Kompatibel sind beide. Wer den Druck ablesen möchte, braucht hier die P51 mit Manometer.","hint":"Welche zwei Eigenschaften sind als Bedarf genannt?","steps":"Prüfe zunächst das Ventil, dann die Druckanzeige.","example":"Wenn beide Pumpen kompatibel sind, kann die Ausstattung über die Wahl entscheiden.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Ein Maß eindeutig beschriften","scene":"Du möchtest auf der kurzen Karte zu F60 die Angabe 64 mm erklären.","ask":"Welche Formulierungen stimmen?","options":["„64 mm Abstand zwischen den passenden Rahmengewinden.“","„Flasche mit genau 64 mm Durchmesser.“","„64 mm misst man am Fahrradrahmen.“","„64 mm Durchmesser der enthaltenen Schrauben.“","„64 mm umfassen die gesamte Flasche.“","„64 mm sind eine Empfehlung für die Lenkerbreite.“"],"answer":[0,2],"why":"64 mm ist der Abstand zwischen den zwei passenden Rahmengewinden. Die passende Flasche hat einen anderen Durchmesserbereich.","hint":"Suche den Gegenstand, an dem die 64 mm gemessen werden.","steps":"Verbinde den Zahlenwert mit einem klaren Bezugswort.","example":"Ein Zahlenschild ohne „Abstand“ lädt zur Verwechslung mit dem Durchmesser ein.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Eine falsche Formulierung auf der Halterkarte korrigieren","scene":"Übungsvariante: Auf dem Entwurf steht „Flaschenmaß 64 mm, Befestigung 72–75 mm“. Schrauben werden erwähnt, der Bezug zum Fahrrad fehlt.","ask":"Welche Änderungen braucht die Karte?","options":["Flaschendurchmesser 72–75 mm angeben.","Die beiden ursprünglichen Zahlen nur größer schreiben.","Abstand 64 mm klar den Rahmengewinden zuordnen.","Ergänzen, dass passende Befestigungsschrauben beiliegen.","„Montage garantiert“ ergänzen, wenn zwei beliebige Gewinde sichtbar sind.","Die Zahlen streichen und nur „passend“ schreiben."],"answer":[0,2,3],"why":"Die Werte waren vertauscht. Die Karte nennt nun Flaschendurchmesser, Gewindeabstand und beiliegende Schrauben getrennt.","hint":"Lies die richtige Zuordnung in der Produktkarte.","steps":"Korrigiere Bezeichnung und Zahlenwert gemeinsam.","example":"Die Lesbarkeit hilft nur, wenn die Daten sachlich stimmen.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Wasserabweisend richtig angeben","scene":"Die Produktkarte von T30 nennt 1,2 Liter Inhalt, verstellbare Klettbänder und wasserabweisendes Material.","ask":"Welche Angaben dürfen auf das Schild?","options":["„Fasst 1,2 Liter.“","„Garantiert vollständig wasserdicht.“","„Wasserabweisend.“","„Befestigung mit verstellbaren Klettbändern.“","„Fasst 12 Liter.“","„Befestigung nur mit festen Schrauben.“"],"answer":[0,2,3],"why":"Volumen, Befestigungsart und die Angabe wasserabweisend sind belegt. Vollständige Wasserdichtheit steht nicht auf der Produktkarte.","hint":"Lies Eigenschaft und Zahl genau.","steps":"Prüfe bei jeder Zeile, ob sie wirklich aus M3 stammt.","example":"„Wasserabweisend“ verspricht weniger als „wasserdicht“.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Zwei kleine Karten aus Produktdaten schreiben","scene":"Übungsvariante: Eine Karte für B80 soll zur Größe am Arm helfen, eine Karte für L10 zum Lenkeranschluss. Das Team überlegt, welche Daten kurz und richtig sind.","ask":"Welche Schildtexte sind belegt?","options":["„B80: Für 20–40 cm Umfang verstellbar.“","„B80: Leuchtet ohne angestrahlt zu werden.“","„L10 vorne: Lenkerdurchmesser 22–32 mm.“","„L10: Die Lenkerangabe beschreibt Vorder- und Rücklichthalterung.“","„B80: Wirft Licht zurück, wenn man es anleuchtet.“","„L10: Passend an jeden Lenker ohne Prüfung.“"],"answer":[0,2,4],"why":"B80 reflektiert Licht und ist für bestimmte Umfänge einstellbar. Das Lenkermaß von L10 betrifft die Halterung des Vorderlichts.","hint":"Achte auf Produkttyp, Einheit und Reichweite der Aussage.","steps":"Ordne jeden Text der passenden Zeile aus M3 zu.","example":"Durchmesser und Umfang können denselben Gegenstand beschreiben, sind aber verschiedene Maße.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Einen gemeinsamen Suchauftrag geben","scene":"Zwei Personen sollen vom Eingang und aus der Fahrradabteilung jeweils den Weg zum Pumpenregal finden.","ask":"Welche Angaben braucht ein vergleichbarer Test?","options":["Beide bekommen dasselbe Suchziel.","Beide beginnen an ihrem festgelegten eigenen Startpunkt.","Die Person aus der Abteilung bekommt die Lösung vorab.","Beide starten an der Pumpe, damit die Wege kürzer sind.","Der erste Hinweis wird nur beim besseren Ergebnis notiert.","Eine Person sucht Pumpen, die andere nur einen Einkaufswagen."],"answer":[0,1],"why":"Dasselbe Ziel und unterschiedliche Startpunkte zeigen, wie die Hinweise aus beiden Laufrichtungen funktionieren.","hint":"Welche Merkmale sollen gleich sein, welche verschieden?","steps":"Trenne Einkaufsziel von Startpunkt.","example":"Ein anderer Start ist sinnvoll, wenn du genau die Sicht aus dieser Richtung prüfen willst.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Nach einer Schildänderung fair vergleichen","scene":"Übungsvariante: Beim ersten Versuch finden Personen vom Eingang die Pumpen sofort. Aus der Fahrradabteilung wird das Schild erst nach einer Runde bemerkt. Ihr dreht es für die nächste Runde.","ask":"Wie prüft das Team die Änderung?","options":["Neue Testpersonen aus beiden Startpunkten ohne Wegführung suchen lassen.","Nur den Eingang testen, weil dort anfangs alles klappte.","Bei beiden notieren, wo der erste Hinweis auffällt.","Durch eine Voraberklärung gezielt die Beobachtung aus der Fahrradabteilung verbessern.","Die neuen Ergebnisse mit denen vor dem Drehen vergleichen.","Das Ergebnis nach der Zahl der Produktkäufe statt dem Suchweg beurteilen."],"answer":[0,2,4],"why":"Die geänderte Ausrichtung muss weiter aus beiden Richtungen funktionieren. Dieselben Beobachtungen erleichtern den Vorher-Nachher-Vergleich.","hint":"Eine Änderung kann eine Richtung verbessern und eine andere verschlechtern.","steps":"Halte Ziel, Rollen und Beobachtung gleich. Ändere nur die Schildstellung.","example":"Ein neuer Standort ist erst dann geprüft, wenn der Test die ursprünglich betroffene Richtung umfasst.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Ein Halt lässt sich nicht ausmessen","scene":"Der Grundriss zeigt freie Wege. Eine Testperson hält mit dem Wagen an, um vor der Gondel zu lesen.","ask":"Warum braucht dein Entwurf die zusätzliche Probe?","options":["Der Wagen kann während des Lesens einen belegten Punkt erzeugen.","Ein freier Plan zeigt schon alle Halte der Kundschaft.","Man muss beobachten, ob eine weitere Person dann vorbeikommt.","Die Länge der Rollenbeschreibung reicht für die Beurteilung der Wege.","Aus dem Preis der Pumpe lässt sich der Wagenstandort ableiten.","Die Lesedauer allein ersetzt die Prüfung des Gangs."],"answer":[0,2],"why":"Das freie Modell beschreibt Möbel. Menschen und Wagen beanspruchen erst beim Einkauf zusätzlichen Platz. Ein Test zeigt mögliche Engstellen.","hint":"Wo steht der Wagen während des Lesens?","steps":"Prüfe die Bewegung einer zweiten Person genau dann.","example":"Ein freier Gang vor Ladenöffnung kann bei einer Lesestelle später enger werden.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine alternative Lesestelle überprüfen","scene":"Übungsvariante: In einer Position bleibt der Wagen am Rand des Hauptgangs stehen. Nach dem Verschieben der Karte bleibt er vor der zweiten Gondelseite stehen. Beide Stellpläne sehen im leeren Modell regelgerecht aus.","ask":"Welche Schritte machen deinen Vergleich aussagekräftig?","options":["Bei beiden Kartenpositionen den Lesehalt mit Wagen nachstellen.","Nur die leeren Grundrisse vergleichen.","In beiden Proben prüfen, ob man an die lange Warenseite gelangt.","Den Haupteingang so lange sperren, bis die Testperson gelesen hat.","Notieren, welcher Weg oder welche Bedienseite tatsächlich beeinträchtigt wird.","Die Karte wählen, die am weitesten vom Eingang entfernt liegt, ohne die Probe zu prüfen."],"answer":[0,2,4],"why":"Die zwei Aufbauten unterscheiden sich erst durch den Halt beim Lesen. Prüfe Bewegung und Bedienseiten in beiden Szenen.","hint":"Welche Position in der Szene wechselt mit der Karte?","steps":"Spiele denselben Einkauf bei beiden Standorten durch.","example":"Eine Verlagerung kann die erste Engstelle lösen und eine zweite erzeugen.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4","M5"]},{"title":"Eine Rückfrage zur Rahmenmessung stellen","scene":"Eine Testperson sagt bei F60: „74 mm habe ich gemessen. Sind das die Schrauben?“","ask":"Was hilft bei der Überarbeitung?","options":["Fragen, an welchem Gegenstand die Person 74 mm gemessen hat.","In der Darstellung 74 mm als Gewindeabstand einsetzen.","Durchmesser der Flasche und Abstand der Gewinde sichtbar voneinander trennen.","Die Karte nur durch ein Flaschenfoto ersetzen.","Mit 75 mm als Rahmenvorgabe korrigieren.","Das Wort „passend“ ohne Maße stehen lassen."],"answer":[0,2],"why":"Eine genaue Rückfrage zeigt die Verwechslung. Eine getrennte Beschriftung macht klar, dass sich die Werte auf Flasche und Fahrrad beziehen.","hint":"Höre, welche beiden Gegenstände vermischt werden.","steps":"Verwende je einen eigenen Eintrag für Durchmesser und Gewindeabstand.","example":"Eine klare Kartenzeile lautet etwa „Abstand am Rahmen: 64 mm“.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Die Rückmeldung vor und nach der Änderung prüfen","scene":"Übungsvariante: Im ersten Versuch erkennt eine Person die richtige Flaschengröße, sagt aber: „Zwei Löcher am Rahmen reichen.“ Ihr wollt die Karte mit einer zweiten Person testen.","ask":"Welche Änderungen und Fragen sind gezielt?","options":["Auf der Karte den Abstand von 64 mm bei den Rahmengewinden nennen.","Die zweite Person nur nach dem Preis des Halters fragen.","Die zweite Person in eigenen Worten sagen lassen, was sie am Fahrrad misst.","Alle Hinweise zum Rahmen durch ein größer gedrucktes Flaschenmaß ersetzen.","Nach dem Versuch zwischen Auffinden und Verstehen der Karte unterscheiden.","Zur Vereinfachung auf der Karte behaupten, dass zwei beliebige Löcher reichen."],"answer":[0,2,4],"why":"Die alte Antwort zeigt fehlendes Verständnis der Montagebedingung. Eine neue Probe mit derselben fachlichen Frage prüft die Erklärung.","hint":"Was hat die erste Person richtig erkannt und was noch nicht?","steps":"Verbessere nur den unklaren Teil und stelle danach eine passende Testfrage.","example":"Ein richtiger Flaschendurchmesser beantwortet keine Frage zum Abstand am Fahrrad.","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Guten ersten Eindruck nachprüfen","scene":"Du findest den Hinweis am Eingang sofort. Danach siehst du, dass der zugehörige Fuß den Hauptgang verengt.","ask":"Welche Reaktionen passen?","options":["Die freie Gangbreite an dieser Stelle kontrollieren.","An der ersten Wahl festhalten, weil du das Schild sofort gefunden hast.","Eine regelgerechte Position suchen und dieselbe Sichtbarkeit erneut testen.","Nur die Schildfarbe ändern.","Die Pflichtfläche auf der Skizze verkleinern.","Eine Beurteilung des Durchgangs vermeiden, weil das Schild gut wirkt."],"answer":[0,2],"why":"Der erste Eindruck ist ein Hinweis zur Sichtbarkeit. Die verpflichtende Gangbreite muss zusätzlich geprüft und eingehalten werden.","hint":"Trenne Sichtbarkeit und Gangbreite.","steps":"Prüfe die Regel und überarbeite anschließend die Position.","example":"Ein klarer Hinweis ist nur dann eine gute Wahl, wenn er am Standort auch zulässig ist.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Eine eigene Empfehlung nach einer Beobachtung ändern","scene":"Übungsvariante: Du bevorzugst einen Hinweis nah an der Gondel. Beim unabhängigen Test sieht man ihn aus der Fahrradabteilung gut, vom Eingang aber erst nach der ersten Abzweigung.","ask":"Wie gehst du damit um?","options":["Den Ort des ersten Hinweises für beide Richtungen festhalten.","Die eigene Annahme mit der Beobachtung abgleichen.","Nur den erfolgreichen Startpunkt als Ergebnis zeigen.","Die zweite Richtung mit einem veränderten Hinweis testen und dabei die freien Wege erhalten.","Das Team die Strecke vorab erklären lassen, damit der neue Test gelingt.","Die Standortwahl allein an der Schriftfarbe festmachen."],"answer":[0,1,3],"why":"Die neue Beobachtung lässt die erste Einschätzung prüfen. Der nächste Entwurf muss Hinführung und freie Wege gemeinsam sichern.","hint":"Dein eigener Startpunkt ist nur eine von zwei möglichen Perspektiven.","steps":"Vergleiche den tatsächlichen ersten Blick mit dem erwarteten und teste eine Änderung.","example":"Mancher Hinweis wirkt je nach Blickrichtung zu früh oder zu spät.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Ein Beispiel zur Auswahl zeigen","scene":"Im kurzen Pitch sagt das Team: „Bei uns erkennt man, welche Pumpe passt.“","ask":"Wodurch wird das nachvollziehbar?","options":["Die Zeile zu den Ventilarten an der Karte zeigen.","Alle Verkaufspreise vorlesen.","Die Zuordnung einer der Pumpen zu einem konkreten Bedarf erklären.","Nur die Laufrichtung kleingedruckt am Rand zeigen.","Die Produktkarte erwähnen, aber nicht zeigen.","Die Druckanzeige als Eigenschaft beider Pumpen ausgeben."],"answer":[0,2],"why":"Eine konkrete Kartenzeile und ein verständliches Auswahlbeispiel belegen, wie die Selbstbedienung funktioniert.","hint":"Welche einzelne Information nutzt jemand beim Einkaufen?","steps":"Zeige Datenzeile und Entscheidung im selben Beispiel.","example":"Durch die Ventilzeile sieht man, welche Pumpen überhaupt infrage kommen.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Ein nachvollziehbares Ergebnis in kurzer Zeit vorstellen","scene":"Übungsvariante: Beim ersten Test stand der Einkaufswagen vor der Bedienseite, als ein Vater die Karte las. Nun hängt die Karte an einer besser nutzbaren Stelle.","ask":"Was sollte in den Pitch?","options":["Im Plan alten und neuen Leseort zeigen.","Nur sagen, dass die Gruppe die Karte anders gestaltet hat.","Die Beobachtung mit Wagen als Anlass für die Veränderung benennen.","Eine passende Produktzeile zeigen, die am neuen Ort weiter gut lesbar ist.","Mit den Preisen aller Artikel beginnen und den Standort später weglassen.","Den Plan ohne Erklärung für eine spätere Prüfung abgeben."],"answer":[0,2,3],"why":"Der Pitch zeigt, wo der Aufbau geändert wurde, was die Probe ergeben hat und wie die Karte beim Auswählen weiterhilft.","hint":"Sammle je eine Planstelle, Beobachtung und Textangabe.","steps":"Verbinde die Veränderung mit Einkauf und Beleg.","example":"Eine kurze Vorher-Nachher-Erklärung ist verständlich, wenn der Ort gezeigt wird.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]}];
